async function run() {
  const pages = figma.root.children;
  const info = pages.map(p => {
    return { name: p.name, id: p.id };
  });

  // Find components in 02 · Components
  const compPage = pages.find(p => p.name.includes("02 · Components"));
  let comps = [];
  if (compPage) {
    const findComps = (node) => {
      if (node.type === "COMPONENT" || node.type === "COMPONENT_SET") {
        comps.push({ name: node.name, id: node.id, type: node.type });
      }
      if ("children" in node) {
        node.children.forEach(findComps);
      }
    };
    compPage.children.forEach(findComps);
  }

  // Find components in 04 · Media
  const mediaPage = pages.find(p => p.name.includes("04 · Media"));
  let mediaComps = [];
  if (mediaPage) {
    const findMedia = (node) => {
      if (node.type === "COMPONENT" || node.type === "COMPONENT_SET") {
        mediaComps.push({ name: node.name, id: node.id, type: node.type });
      }
      if ("children" in node) {
        node.children.forEach(findMedia);
      }
    };
    mediaPage.children.forEach(findMedia);
  }

  return JSON.stringify({
    pages: info,
    components: comps,
    media: mediaComps
  }, null, 2);
}
return run();

