  await figma.loadFontAsync({ family: "Poppins", style: "Regular" });
  await figma.loadFontAsync({ family: "Poppins", style: "Medium" });
  await figma.loadFontAsync({ family: "Poppins", style: "Semi Bold" });
  await figma.loadFontAsync({ family: "Poppins", style: "Bold" });
  return "Fonts loaded successfully";
}
return checkFonts();

async function checkWorkspace() {
  const pages = figma.root.children;
  const workspace = pages.find(p => p.name.includes("03 · Workspace"));
  if (workspace) {
    return JSON.stringify(workspace.children.map(c => ({ name: c.name, id: c.id, type: c.type })));
  }
  return "Workspace not found";
}
return checkWorkspace();

async function inspectComponents() {
  const pages = figma.root.children;
  const compPage = pages.find(p => p.name.includes("02 · Components"));
  if (!compPage) return "No components page";
  const btn = compPage.findOne(node => node.name === "Button");
  const tf = compPage.findOne(node => node.name === "Text Field");

  const getProps = (node) => {
    if (!node) return null;
    return {
      name: node.name,
      width: node.width,
      height: node.height,
      type: node.type,
      children: node.children ? node.children.map(c => ({ name: c.name, type: c.type, x: c.x, y: c.y, width: c.width, height: c.height })) : []
    };
  };
  return JSON.stringify({ btn: getProps(btn), tf: getProps(tf) }, null, 2);
}
return inspectComponents();

