async function buildPhase1() {
  // Load fonts
  await figma.loadFontAsync({ family: "Volkhov", style: "Regular" });
  await figma.loadFontAsync({ family: "Volkhov", style: "Bold" });
  await figma.loadFontAsync({ family: "Poppins", style: "Regular" });
  await figma.loadFontAsync({ family: "Poppins", style: "Medium" });
  await figma.loadFontAsync({ family: "Poppins", style: "Semi Bold" });
  await figma.loadFontAsync({ family: "Poppins", style: "Bold" });

  const pages = figma.root.children;
  let workspace = pages.find(p => p.name.includes("03 · Workspace"));
  if (!workspace) {
    workspace = figma.createPage();
    workspace.name = "03 · Workspace";
  }
  await figma.setCurrentPageAsync(workspace);

  // Helper map for media components
  const mediaPage = pages.find(p => p.name.includes("04 · Media"));
  const mediaMap = {};
  if (mediaPage) {
    mediaPage.findAll(n => n.type === "COMPONENT").forEach(c => {
      mediaMap[c.name] = c;
    });
  }

  function getMediaInstance(name, width, height) {
    if (mediaMap[name]) {
      const inst = mediaMap[name].createInstance();
      if (width && height) {
        inst.resize(width, height);
      }
      return inst;
    }
    // Fallback frame if component not found
    const f = figma.createFrame();
    f.name = name;
    f.resize(width || 100, height || 100);
    f.fills = [{ type: 'SOLID', color: { r: 0.9, g: 0.9, b: 0.9 } }];
    return f;
  }

  function createText(text, fontSize = 14, fontWeight = "Regular", color = { r: 0.1, g: 0.1, b: 0.1 }, isVolkhov = false) {
    const t = figma.createText();
    t.fontName = { family: isVolkhov ? "Volkhov" : "Poppins", style: fontWeight };
    t.fontSize = fontSize;
    t.characters = text;
    t.fills = [{ type: 'SOLID', color }];
    return t;
  }

  function createBtn(label, bg = { r: 0, g: 0, b: 0 }, textColor = { r: 1, g: 1, b: 1 }, width = 160, height = 48) {
    const f = figma.createFrame();
    f.name = "Button";
    f.resize(width, height);
    f.cornerRadius = 8;
    f.fills = [{ type: 'SOLID', color: bg }];
    f.layoutMode = "HORIZONTAL";
    f.primaryAxisAlignItems = "CENTER";
    f.counterAxisAlignItems = "CENTER";

    const t = createText(label, 14, "Medium", textColor);
    f.appendChild(t);
    return f;
  }

  function createInputField(label, placeholder, width = 420) {
    const wrap = figma.createFrame();
    wrap.name = "Text Field Wrap";
    wrap.layoutMode = "VERTICAL";
    wrap.itemSpacing = 6;
    wrap.resize(width, 76);
    wrap.fills = [];

    if (label) {
      const lbl = createText(label, 13, "Medium", { r: 0.2, g: 0.2, b: 0.2 });
      wrap.appendChild(lbl);
    }

    const inp = figma.createFrame();
    inp.name = "Input Container";
    inp.resize(width, 48);
    inp.cornerRadius = 8;
    inp.strokes = [{ type: 'SOLID', color: { r: 0.85, g: 0.85, b: 0.85 } }];
    inp.strokeWeight = 1;
    inp.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
    inp.layoutMode = "HORIZONTAL";
    inp.counterAxisAlignItems = "CENTER";
    inp.paddingLeft = 16;
    inp.paddingRight = 16;

    const txt = createText(placeholder, 14, "Regular", { r: 0.5, g: 0.5, b: 0.5 });
    inp.appendChild(txt);
    wrap.appendChild(inp);
    return wrap;
  }

  // --- HEADER CREATORS ---
  function createHomeHeader() {
    const header = figma.createFrame();
    header.name = "Header";
    header.resize(1920, 100);
    header.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
    header.layoutMode = "HORIZONTAL";
    header.primaryAxisAlignItems = "SPACE_BETWEEN";
    header.counterAxisAlignItems = "CENTER";
    header.paddingLeft = 160;
    header.paddingRight = 160;

    const logo = createText("FASCO", 36, "Bold", { r: 0, g: 0, b: 0 }, true);
    logo.name = "FASCO wordmark";

    const nav = figma.createFrame();
    nav.name = "Nav Links";
    nav.layoutMode = "HORIZONTAL";
    nav.itemSpacing = 40;
    nav.counterAxisAlignItems = "CENTER";
    nav.fills = [];

    const navHome = createText("Home", 15, "Bold", { r: 0, g: 0, b: 0 });
    const navDeals = createText("Deals", 15, "Regular", { r: 0.4, g: 0.4, b: 0.4 });
    const navNew = createText("New Arrivals", 15, "Regular", { r: 0.4, g: 0.4, b: 0.4 });
    const navPkg = createText("Packages", 15, "Regular", { r: 0.4, g: 0.4, b: 0.4 });

    nav.appendChild(navHome);
    nav.appendChild(navDeals);
    nav.appendChild(navNew);
    nav.appendChild(navPkg);

    const actions = figma.createFrame();
    actions.name = "Actions";
    actions.layoutMode = "HORIZONTAL";
    actions.itemSpacing = 24;
    actions.counterAxisAlignItems = "CENTER";
    actions.fills = [];

    const signIn = createText("Sign in", 15, "Medium", { r: 0.1, g: 0.1, b: 0.1 });
    signIn.name = "Sign in";
    const signUpBtn = createBtn("Sign Up", { r: 0, g: 0, b: 0 }, { r: 1, g: 1, b: 1 }, 110, 44);
    signUpBtn.name = "Sign Up";

    actions.appendChild(signIn);
    actions.appendChild(signUpBtn);

    header.appendChild(logo);
    header.appendChild(nav);
    header.appendChild(actions);
    return header;
  }

  function createStoreHeader(activeItem = "Shop", cartCount = 0) {
    const header = figma.createFrame();
    header.name = "Header";
    header.resize(1920, 100);
    header.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
    header.layoutMode = "HORIZONTAL";
    header.primaryAxisAlignItems = "SPACE_BETWEEN";
    header.counterAxisAlignItems = "CENTER";
    header.paddingLeft = 160;
    header.paddingRight = 160;

    const logo = createText("FASCO", 36, "Bold", { r: 0, g: 0, b: 0 }, true);
    logo.name = "FASCO wordmark";

    const nav = figma.createFrame();
    nav.name = "Nav Links";
    nav.layoutMode = "HORIZONTAL";
    nav.itemSpacing = 40;
    nav.counterAxisAlignItems = "CENTER";
    nav.fills = [];

    const items = ["Home", "Shop", "Products", "Pages"];
    items.forEach(it => {
      const isCurrent = (it === activeItem);
      const t = createText(it, 15, isCurrent ? "Bold" : "Regular", isCurrent ? { r: 0, g: 0, b: 0 } : { r: 0.4, g: 0.4, b: 0.4 });
      t.name = it;
      nav.appendChild(t);
    });

    const icons = figma.createFrame();
    icons.name = "Icons Bar";
    icons.layoutMode = "HORIZONTAL";
    icons.itemSpacing = 20;
    icons.counterAxisAlignItems = "CENTER";
    icons.fills = [];

    const searchInst = getMediaInstance("Icon_Search", 22, 22);
    searchInst.name = "search";
    const accountInst = getMediaInstance("Icon_Account", 22, 22);
    accountInst.name = "account";
    const wishlistInst = getMediaInstance("Icon_Star", 22, 22);
    wishlistInst.name = "wishlist";

    const cartWrap = figma.createFrame();
    cartWrap.name = "cart";
    cartWrap.resize(32, 32);
    cartWrap.fills = [];
    const cartInst = getMediaInstance("Icon_Cart", 22, 22);
    cartInst.x = 0; cartInst.y = 5;
    cartWrap.appendChild(cartInst);

    if (cartCount > 0) {
      const badge = figma.createFrame();
      badge.name = "Cart Count";
      badge.resize(18, 18);
      badge.cornerRadius = 9;
      badge.fills = [{ type: 'SOLID', color: { r: 0.9, g: 0.2, b: 0.2 } }];
      badge.layoutMode = "HORIZONTAL";
      badge.primaryAxisAlignItems = "CENTER";
