    if (mediaMap[name]) {
      const inst = mediaMap[name].createInstance();
      if (width && height) {
        inst.resize(width, height);
      }
      return inst;
    }
    const f = figma.createFrame();
    f.name = name;
    f.resize(width || 100, height || 100);
    f.fills = [{ type: 'SOLID', color: { r: 0.9, g: 0.9, b: 0.9 } }];
    return f;
