    const t = figma.createText();
    t.fontName = { family: isVolkhov ? "Volkhov" : "Poppins", style: fontWeight };
    t.fontSize = fontSize;
    t.characters = text;
    t.fills = [{ type: 'SOLID', color }];
    return t;
  }

