    const inp = figma.createFrame();
    inp.name = "Input Container";
    inp.resize(width, 48);
    inp.cornerRadius = 8;
    inp.strokes = [{ type: 'SOLID', color: { r: 0.85, g: 0.85, b: 0.85 } }];
