async function checkWorkspaceContent() {
  const pages = figma.root.children;
  const workspace = pages.find(p => p.name.includes("03 · Workspace"));
  if (workspace) {
    return workspace.children.map(c => ({ name: c.name, id: c.id, x: c.x, y: c.y, width: c.width, height: c.height }));
  }
  return [];
}
return checkWorkspaceContent();

async function addPrototypeConnections() {
  const pages = figma.root.children;
  const workspace = pages.find(p => p.name.includes("03 · Workspace"));
  if (!workspace) return "Workspace not found";

  const frames = {};
  workspace.children.forEach(c => {
    frames[c.name] = c;
  });

  const getTargetId = (name) => {
    return frames[name] ? frames[name].id : null;
  };

  const addReaction = (sourceNode, targetFrameName) => {
    if (!sourceNode) return;
    const targetId = getTargetId(targetFrameName);
    if (!targetId) return;
    sourceNode.reactions = [
      {
        trigger: { type: "ON_CLICK" },
        actions: [
          {
            type: "NODE",
            destinationId: targetId,
            navigation: "NAVIGATE",
            transition: null
          }
        ]
      }
    ];
  };

  // --- 01_Home Reactions ---
  const fHome = frames["01_Home"];
  if (fHome) {
    // Header Links
    const header = fHome.findOne(n => n.name === "Header");
    if (header) {
      const signIn = header.findOne(n => n.name === "Sign in");
      addReaction(signIn, "08_Sign_In");

      const signUp = header.findOne(n => n.name === "Sign Up");
      addReaction(signUp, "07_Sign_Up");
    }

    // Hero: SHOP NOW
    const shopNow = fHome.findOne(n => n.name === "SHOP NOW");
    addReaction(shopNow, "02_Shop");

    // New Arrivals: View More
    const viewMore = fHome.findOne(n => n.name === "View More");
    addReaction(viewMore, "02_Shop");
  }

  // --- 02_Shop Reactions ---
  const fShop = frames["02_Shop"];
  if (fShop) {
    // Header
    const header = fShop.findOne(n => n.name === "Header");
    if (header) {
      const account = header.findOne(n => n.name === "account");
      addReaction(account, "08_Sign_In");

      const cart = header.findOne(n => n.name === "cart");
      addReaction(cart, "05_Cart");

      const navHome = header.findOne(n => n.name === "Home");
      addReaction(navHome, "01_Home");
    }

    // Product Card -> 03_Product
    // Let's link any Product Card
    fShop.findAll(n => n.name.startsWith("Product Card ")).forEach(card => {
      addReaction(card, "03_Product");
    });
  }

  // --- 03_Product Reactions ---
  const fProd = frames["03_Product"];
  if (fProd) {
    // Header
    const header = fProd.findOne(n => n.name === "Header");
    if (header) {
      const navShop = header.findOne(n => n.name === "Shop");
      addReaction(navShop, "02_Shop");

      const navHome = header.findOne(n => n.name === "Home");
      addReaction(navHome, "01_Home");

      const cart = header.findOne(n => n.name === "cart");
      addReaction(cart, "05_Cart");
    }

    // Add to cart button -> 04_Mini_Cart
    const atc = fProd.findOne(n => n.name === "Add to cart");
    addReaction(atc, "04_Mini_Cart");
  }

  // --- 04_Mini_Cart Reactions ---
  const fMini = frames["04_Mini_Cart"];
  if (fMini) {
    const miniCart = fMini.findOne(n => n.name === "Mini cart");
    if (miniCart) {
      const close = miniCart.findOne(n => n.name === "close");
      addReaction(close, "03_Product");

      const checkout = miniCart.findOne(n => n.name === "Checkout");
      addReaction(checkout, "06_Checkout");

      const viewCart = miniCart.findOne(n => n.name === "View Cart");
      addReaction(viewCart, "05_Cart");
    }
  }

  // --- 05_Cart Reactions ---
  const fCart = frames["05_Cart"];
  if (fCart) {
    // Header
    const header = fCart.findOne(n => n.name === "Header");
    if (header) {
      const navHome = header.findOne(n => n.name === "Home");
      addReaction(navHome, "01_Home");

      const navShop = header.findOne(n => n.name === "Shop");
      addReaction(navShop, "02_Shop");
    }

    // Denim Jacket Product Link
    const denimJacket = fCart.findOne(n => n.name === "Denim Jacket" && n.type === "TEXT");
    addReaction(denimJacket, "03_Product");

    // Checkout
    const cartSummary = fCart.findOne(n => n.name === "Cart Summary Card");
    if (cartSummary) {
      const chkBtn = cartSummary.findOne(n => n.name === "Checkout");
      addReaction(chkBtn, "06_Checkout");
    }
  }

  // --- 06_Checkout Reactions ---
  const fChk = frames["06_Checkout"];
  if (fChk) {
    // Header
    const header = fChk.findOne(n => n.name === "Header");
    if (header) {
      const navHome = header.findOne(n => n.name === "Home");
      addReaction(navHome, "01_Home");
    }

    // Create Account Link
    const createAcc = fChk.findOne(n => n.name === "Create Account");
    addReaction(createAcc, "07_Sign_Up");
  }

  // --- 07_Sign_Up Reactions ---
  const fSU = frames["07_Sign_Up"];
  if (fSU) {
    const createAcc = fSU.findOne(n => n.name === "Create Account" && n.type === "FRAME");
    addReaction(createAcc, "01_Home");

    const login = fSU.findOne(n => n.name === "Already have an account? Login");
    addReaction(login, "08_Sign_In");
  }

  // --- 08_Sign_In Reactions ---
  const fSI = frames["08_Sign_In"];
  if (fSI) {
    const signIn = fSI.findOne(n => n.name === "Sign In" && n.type === "FRAME");
    addReaction(signIn, "01_Home");

    const register = fSI.findOne(n => n.name === "Register Now");
    addReaction(register, "07_Sign_Up");

    const forgot = fSI.findOne(n => n.name === "Forgot Password?");
    addReaction(forgot, "09_Forgot_Password");
  }

  // --- 09_Forgot_Password Reactions ---
  const fFP = frames["09_Forgot_Password"];
  if (fFP) {
    const sendCode = fFP.findOne(n => n.name === "Send Confirmation Code" && n.type === "FRAME");
    addReaction(sendCode, "10_Confirmation_Code");

    const login = fFP.findOne(n => n.name === "Already have an account? Login");
    addReaction(login, "08_Sign_In");
  }

  // --- 10_Confirmation_Code Reactions ---
  const fCC = frames["10_Confirmation_Code"];
  if (fCC) {
    const recover = fCC.findOne(n => n.name === "Recover Account" && n.type === "FRAME");
    addReaction(recover, "11_New_Password");
  }

  // --- 11_New_Password Reactions ---
  const fNP = frames["11_New_Password"];
  if (fNP) {
    const submit = fNP.findOne(n => n.name === "Submit" && n.type === "FRAME");
    addReaction(submit, "01_Home");
  }

  return "Prototype connections configured successfully";
}

return addPrototypeConnections();
